        }
        .container {
            background-color: white;
            padding: 2rem;
            border-radius: 15px;
            box-shadow: 0 4px 8px rgba(0,0,0,0.1);
            text-align: center;
            max-width: 400px;
            width: 90%;
        }
        h1 {
            color: #ff6b6b;
            margin-bottom: 1rem;
        }
        .cereal-display {
            font-size: 1.8rem;
            font-weight: bold;
            color: #4a4a4a;
            margin: 1.5rem 0;
            padding: 1rem;
            background-color: #fff9c4;
            border-radius: 10px;
            min-height: 80px;
            display: flex;
            align-items: center;
            justify-content: center;
        }
        button {
            background-color: #ff6b6b;
            color: white;
            border: none;
            padding: 0.8rem 1.5rem;
            font-size: 1rem;
            border-radius: 25px;
            cursor: pointer;
            transition: background-color 0.3s;
        }
        button:hover {
            background-color: #ff5252;
        }
        .subtitle {
            color: #888;
            font-size: 0.9rem;
            margin-top: 1rem;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>🥣 Breakfast Cereal Chooser</h1>
        <div class="cereal-display" id="cerealDisplay">Click the button!</div>
        <button onclick="chooseCereal()">Choose a Cereal</button>
        <p class="subtitle">Can't decide? Let us pick for you!</p>
    </div>

    <script>
        const cereals = [
            "Cheerios",
            "Frosted Flakes",
            "Froot Loops",
            "Lucky Charms",
            "Cap'n Crunch",
            "Cinnamon Toast Crunch",
            "Raisin Bran",
            "Special K",
            "Corn Flakes",
            "Rice Krispies",
            "Honey Nut Cheerios",
            "Fruity Pebbles",
            "Apple Jacks",
            "Trix",
            "Reese's Puffs"
        ];

        function chooseCereal() {
            const randomIndex = Math.floor(Math.random() * cereals.length);
            const chosenCereal = cereals[randomIndex];
            document.getElementById('cerealDisplay').textContent = chosenCereal;
        }

        // Choose a cereal on page load
        window.onload = chooseCereal;
    </script>
</body>
</html>
```

Save this as an `.html` file and open it in any browser to get a random cereal suggestion each time you click the button (or refresh the page).

