<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Nike - Just Do It</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Anton&family=Inter:wght@300;400;600;800&display=swap" rel="stylesheet">
    <style>
        /* Custom styles */
        body {
            font-family: 'Inter', sans-serif;
        }
        .font-anton {
            font-family: 'Anton', sans-serif;
        }
        .nike-orange {
            color: #f97316;
        }
        .bg-nike-orange {
            background-color: #f97316;
        }
        .bg-nike-black {
            background-color: #000000;
        }
        .bg-nike-white {
            background-color: #ffffff;
        }
        .swoosh {
            position: relative;
            display: inline-block;
        }
        .swoosh::after {
            content: '';
            position: absolute;
            bottom: 0;
            right: -5px;
            width: 30px;
            height: 15px;
            background: #000;
            border-radius: 50% 50% 0 0;
            transform: rotate(-30deg);
            opacity: 0.1;
        }
        .hero-bg {
            background-image: linear-gradient(rgba(0,0,0,0.3), rgba(0,0,0,0.6)), url('https://images.unsplash.com/photo-1556906781-9a412961c28c?ixlib=rb-4.0.3&auto=format&fit=crop&w=1920&q=80');
            background-size: cover;
            background-position: center;
        }
        .product-card:hover .product-img {
            transform: scale(1.05);
        }
        .product-img {
            transition: transform 0.5s ease;
        }
        .animate-fade-in {
            animation: fadeIn 1s ease-in-out;
        }
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .ticker-wrap {
            overflow: hidden;
            white-space: nowrap;
        }
        .ticker {
            display: inline-block;
            animation: ticker 30s linear infinite;
        }
        @keyframes ticker {
            0% { transform: translateX(0); }
            100% { transform: translateX(-50%); }
        }
    </style>
</head>
