                if (stored) {
                    try {
                        tasks = JSON.parse(stored);
                    } catch (e) {
                        tasks = [];
                    }
                }
            }

            function saveTasks() {
                localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
            }

            function generateId() {
                return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
            }

            function createTaskElement(task) {
                const div = document.createElement('div');
                div.className = `task ${task.color}`;
                div.draggable = true;
                div.dataset.id = task.id;

                const title = document.createElement('div');
                title.className = 'task-title';
                title.textContent = task.title;
                div.appendChild(title);

                const actions = document.createElement('div');
                actions.className = 'task-actions';

                // Left arrow (move to previous column)
                const leftBtn = document.createElement('button');
                leftBtn.className = 'move-btn';
                leftBtn.innerHTML = '←';
                leftBtn.title = 'Move left';
                leftBtn.dataset.direction = 'left';
                leftBtn.dataset.taskId = task.id;
                if (task.column === 'todo') {
                    leftBtn.style.visibility = 'hidden';
                }
                actions.appendChild(leftBtn);

                // Right arrow (move to next column)
                const rightBtn = document.createElement('button');
                rightBtn.className = 'move-btn';
                rightBtn.innerHTML = '→';
                rightBtn.title = 'Move right';
                rightBtn.dataset.direction = 'right';
                rightBtn.dataset.taskId = task.id;
                if (task.column === 'done') {
                    rightBtn.style.visibility = 'hidden';
                }
                actions.appendChild(rightBtn);

                // Delete button
                const delBtn = document.createElement('button');
                delBtn.className = 'delete-btn';
                delBtn.innerHTML = '×';
                delBtn.title = 'Delete task';
                delBtn.dataset.taskId = task.id;
                actions.appendChild(delBtn);

                div.appendChild(actions);

                // Drag events
                div.addEventListener('dragstart', function(e) {
                    e.dataTransfer.setData('text/plain', task.id);
                    e.dataTransfer.effectAllowed = 'move';
                    setTimeout(() => div.classList.add('dragging'), 0);
                });

                div.addEventListener('dragend', function() {
                    div.classList.remove('dragging');
                });

                return div;
            }

            function renderTasks() {
                // Clear all columns
                document.querySelectorAll('.task-list').forEach(list => {
                    list.innerHTML = '';
                });

                // Group tasks by column
                const columns = {
                    todo: [],
                    inprogress: [],
                    done: []
                };

                tasks.forEach(task => {
                    if (columns[task.column]) {
                        columns[task.column].push(task);
                    }
                });

                // Render each column
                Object.keys(columns).forEach(col => {
                    const list = document.querySelector(`.task-list[data-column="${col}"]`);
                    if (!list) return;

                    if (columns[col].length === 0) {
                        const empty = document.createElement('div');
                        empty.className = 'empty-message';
                        empty.textContent = 'No tasks here';
                        list.appendChild(empty);
                    } else {
                        columns[col].forEach(task => {
                            list.appendChild(createTaskElement(task));
                        });
                    }
                });
            }

            function addTask() {
                const input = document.getElementById('taskInput');
                const colorSelect = document.getElementById('colorSelect');
                const columnSelect = document.getElementById('columnSelect');

                const title = input.value.trim();
                if (!title) {
                    input.focus();
                    return;
                }

                const newTask = {
                    id: generateId(),
                    title: title,
                    color: colorSelect.value,
                    column: columnSelect.value
                };

                tasks.push(newTask);
                saveTasks();
                renderTasks();
                input.value = '';
                input.focus();
            }

            function deleteTask(taskId) {
                tasks = tasks.filter(t => t.id !== taskId);
                saveTasks();
                renderTasks();
            }

            function moveTask(taskId, direction) {
                const task = tasks.find(t => t.id === taskId);
                if (!task) return;

                const columnOrder = ['todo', 'inprogress', 'done'];
                const currentIndex = columnOrder.indexOf(task.column);
                let newIndex = currentIndex;

                if (direction === 'left' && currentIndex > 0) {
                    newIndex = currentIndex - 1;
                } else if (direction === 'right' && currentIndex < columnOrder.length - 1) {
                    newIndex = currentIndex + 1;
                }

                if (newIndex !== currentIndex) {
                    task.column = columnOrder[newIndex];
                    saveTasks();
                    renderTasks();
                }
            }

            function handleMoveButtonClick(e) {
                const btn = e.target.closest('button');
                if (!btn) return;

                if (btn.classList.contains('move-btn')) {
                    const taskId = btn.dataset.taskId;
                    const direction = btn.dataset.direction;
                    if (taskId && direction) {
                        moveTask(taskId, direction);
                    }
                } else if (btn.classList.contains('delete-btn')) {
                    const taskId = btn.dataset.taskId;
                    if (taskId) {
                        deleteTask(taskId);
                    }
                }
            }

            function setupDragAndDrop() {
                const columns = document.querySelectorAll('.task-list');

                columns.forEach(column => {
                    column.addEventListener('dragover', function(e) {
                        e.preventDefault();
                        e.dataTransfer.dropEffect = 'move';
                        column.classList.add('drag-over');
                    });

                    column.addEventListener('dragleave', function() {
                        column.classList.remove('drag-over');
                    });

                    column.addEventListener('drop', function(e) {
                        e.preventDefault();
                        column.classList.remove('drag-over');

                        const taskId = e.dataTransfer.getData('text/plain');
                        if (!taskId) return;

                        const newColumn = column.dataset.column;
                        const task = tasks.find(t => t.id === taskId);
                        if (task && task.column !== newColumn) {
                            task.column = newColumn;
                            saveTasks();
                            renderTasks();
                        }
                    });
                });
            }

            // Event listeners
            document.getElementById('addTask').addEventListener('click', addTask);
            document.getElementById('taskInput').addEventListener('keypress', function(e) {
                if (e.key === 'Enter') addTask();
            });

            // Use event delegation for move/delete buttons
            document.querySelector('.board').addEventListener('click', handleMoveButtonClick);

            // Initialize
            loadTasks();
            if (tasks.length === 0) {
                // Optional: add sample tasks
                tasks = [
                    { id: generateId(), title: 'Welcome to your Kanban board!', color: 'priority-low', column: 'todo' },
                    { id: generateId(), title: 'Drag tasks between columns', color: 'priority-medium', column: 'inprogress' },
                    { id: generateId(), title: 'Try adding a new task ↑', color: 'priority-high', column: 'done' }
                ];
                saveTasks();
            }
            renderTasks();
            setupDragAndDrop();
        })();
    </script>
</body>
</html>
